# COPY — generated by build_repo_mirror.R. Do not edit here. Working copy: data_workspace_2026-07/ch3_pipeline_restored/scripts/build_fig_appendix_backbench_frontbench.R
# build_fig_appendix_backbench_frontbench.R
#
# Appendix robustness figure — self-regarding ratio, backbench vs frontbench,
# 1979-2019 (Blumenau & Damiani data, same sample as the headline series).
# PJ, 7 Sep: the career/office dictionary terms fire mechanically off HOLDING
# a ministerial/shadow role, and frontbench speaking share changed a lot over
# the period — this figure/table (64q_backbench_frontbench_split.R) tests
# whether the declining trend survives WITHIN each group, not just in the
# compositional aggregate. It does (both decline; frontbench declines MORE).
#
# House style: same theme file/greyscale as Fig 3.1-3.3, but this is an
# appendix diagnostic, not a numbered book figure (Figure 3.X numbering is
# PJ's own call to assign).
#
# OUTPUT: figures/ch3_backbench_frontbench_split.png

suppressMessages({library(dplyr); library(readr); library(ggplot2); library(tidyr)})

.ROOT <- local({
  a <- commandArgs(trailingOnly = FALSE)
  m <- grep("^--file=", a, value = TRUE)
  if (length(m) == 1) normalizePath(file.path(dirname(sub("^--file=", "", m)), ".."))
  else getwd()
})
PROJECT   <- .ROOT
WKBD_ROOT <- normalizePath(file.path(PROJECT, "..", ".."))
source(file.path(WKBD_ROOT, "data_workspace_2026-07", "figure_house_theme.R"))

d <- read_csv(file.path(WKBD_ROOT, "online_appendix/ch3_backbench_frontbench_split.csv"),
              show_col_types = FALSE)

long_d <- d |>
  select(year, backbench_ratio, frontbench_ratio) |>
  pivot_longer(-year, names_to = "group", values_to = "ratio") |>
  mutate(group = recode(group, backbench_ratio = "Backbench", frontbench_ratio = "Frontbench"))

CANVAS_W <- house_width_in()

p <- ggplot(long_d, aes(year, ratio, linetype = group)) +
  geom_line(colour = "#000000", linewidth = 0.8) +
  geom_point(colour = "#000000", size = 0.9) +
  annotate("text", x = 1982, y = 0.475, label = "Frontbench", colour = "grey35",
           fontface = "italic", size = mm_for(PRINTED$caption, CANVAS_W)) +
  annotate("text", x = 1988, y = 0.383, label = "Backbench", colour = "grey35",
           fontface = "italic", size = mm_for(PRINTED$caption, CANVAS_W)) +
  scale_linetype_manual(values = c("Backbench" = "solid", "Frontbench" = "dashed")) +
  scale_x_continuous(breaks = seq(1980, 2015, 5), limits = c(1979, 2019)) +
  scale_y_continuous(labels = scales::percent_format(accuracy = 1)) +
  guides(linetype = "none") +
  labs(
    title = "Self-regarding speech: backbench vs frontbench, 1979-2019",
    x = NULL, y = "Self-regarding ratio (mean)"
  ) +
  house_print(CANVAS_W)

OUT <- file.path(PROJECT, "figures/ch3_backbench_frontbench_split.png")
ggsave(OUT, p, width = CANVAS_W, height = CANVAS_W * 0.55, dpi = HOUSE_DPI, bg = "white")
cat("Figure saved:", OUT, "\n")
